    /// full prime by resolving to an already-cached witness).
    fn inner_install_pointer_unlocked(
        &self,
        inner: &mut CacheState,
        key: InternedKey,
        witness: WitnessKey,
        shared: bool,
    ) -> crate::Result<()> {
        // If this key already points somewhere, decrement the old entry.
