                e.refcount = e.refcount.saturating_sub(1);
                if e.refcount == 0 {
                    inner.entries.remove(&old_w);
                    inner.stats.invalidations += 1;
                    inner.per_backend_mut(&key.0).invalidations += 1;
                    inner.per_collection_mut(&key).invalidations += 1;
