    query: &[f32],
    k: usize,
    rerank_factor_override: Option<usize>,
) -> crate::Result<Vec<(u64, f32)>> {
    let interned = intern_cache_key(key);
    self.search_cached_with_rerank_interned(&interned, query, k, rerank_factor_override)
}

