    pub fn register(
        &self,
        collection: impl Into<String>,
        filename: impl Into<String>,
    ) -> Result<()> {
        let filename = filename.into();
        Self::validate_filename(&filename)?;
        let mut idx = self.index.write().unwrap();
        idx.insert(collection.into(), filename);
        Ok(())
