//! `IpfsBackend` — `BackendAdapter` over IPFS for bundle distribution
//! (ADR-005). Talks to kubo via plain HTTP RPC.

use std::collections::HashMap;
use std::sync::{Arc, RwLock};

use serde::Deserialize;

