    #[test]
    fn ts_format_is_iso8601() {
        let ts = now_ts();
        assert_eq!(ts.len(), 24, "len = {} ({ts})", ts.len());
        assert_eq!(&ts[10..11], "T");
        assert_eq!(&ts[19..20], ".");
        assert_eq!(&ts[23..24], "Z");
    }

    #[test]
    fn tail_returns_recent_entries_in_emit_order() {
        let sink = AuditSink::stderr();
        for i in 0..5 {
