#[tokio::test]
async fn backpressure_response_carries_advice_block() {
    use ruvector_rulake_mcp::planner::BackpressureReason;
    let (lake, _, _) = make_lake(50, 16);
    let server = RuLakeMcpServer::from_lake(
        Arc::clone(&lake),
