    let mut mps = Mps::zero_state(n, bond_dim_cap);

    let in_range = |q: u8| -> Result<u8, TensorNetworkError> {
        if q >= n {
            Err(TensorNetworkError::QubitIndexOutOfRange {
                qubit: q,
                n_qubits: n,
            })
        } else {
            Ok(q)
        }
    };

   return Err(TensorNetworkError::ZeroBondDim);
