/// Wire-format mirror of `rulake::bundle::Generation`. `untagged`
/// means a JSON `7` deserializes to `Num(7)` and `"abc"` to `Opaque("abc")`.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(untagged)]
enum Generation {
    Num(u64),
    Opaque(String),
}

impl Generation {
    fn hash_bytes(&self) -> Vec<u8> {
        match self {
            Self::Num(n) => {
                let mut out = Vec::with_capacity(1 + 8);
                out.push(GEN_TAG_NUM);
                out.extend_from_slice(&n.to_le_bytes());
                out
            }
            Self::Opaque(s) => {
                let mut out = Vec::with_capacity(1 + s.len());
                out.push(GEN_TAG_OPAQUE);
                out.extend_from_slice(s.as_bytes());
                out
            }
        }
    }

    fn pretty(&self) -> String {
        match self {
            Self::Num(n) => format!("Num({n})"),
            Self::Opaque(s) => format!("Opaque(\"{s}\")"),
        }
    }
}

